下面给出一个 **通用、易用** 的 `debounce`（防抖）实现。  
它可以：

- **延迟**：在连续触发时只在最后一次触发后 `wait` 毫秒才真正执行回调；
- **可选立即执行**：`immediate` 为 `true` 时，第一次触发立即执行，随后 `wait` 毫秒内的触发会被忽略；
- **支持 `this` 与参数**：返回的包装函数会保持原函数的 `this` 与参数；
- **支持取消**：返回的包装函数带有 `cancel` 方法，可手动取消等待中的执行。

```js
/**
 * 防抖（debounce）函数
 *
 * @param {Function} fn      要包装的原函数
 * @param {number}   wait    延迟时间（毫秒）
 * @param {boolean}  immediate 是否立即执行（默认 false）
 * @returns {Function} 包装后的函数
 *
 * 用法：
 *   const debounced = debounce(() => console.log('tick'), 300);
 *   window.addEventListener('resize', debounced);
 *
 * 取消：
 *   debounced.cancel();
 */
function debounce(fn, wait, immediate = false) {
  let timeoutId = null;   // 当前计时器 ID
  let lastArgs;           // 上一次调用的参数
  let lastThis;           // 上一次调用的 this

  const debounced = function (...args) {
    lastArgs = args;
    lastThis = this;

    // 如果是立即执行模式且没有正在等待的计时器
    if (immediate && !timeoutId) {
      fn.apply(lastThis, lastArgs);
    }

    // 清除旧计时器
    if (timeoutId) clearTimeout(timeoutId);

    // 重新设置计时器
    timeoutId = setTimeout(() => {
      timeoutId = null;          // 计时器完成后置空
      if (!immediate) {          // 非立即执行时才真正调用
        fn.apply(lastThis, lastArgs);
      }
    }, wait);
  };

  // 取消功能
  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debounced;
}
```

### 说明

| 参数 | 说明 | 默认值 |
|------|------|--------|
| `fn` | 需要防抖的原函数 | 必须 |
| `wait` | 延迟时间（毫秒） | 必须 |
| `immediate` | 是否立

